function solve(capacity, accesses) {
  if (capacity <= 0) return [];
  const cache = [];
  const evicted = [];
  for (let t = 0; t < accesses.length; t++) {
    const key = accesses[t];
    let hit = null;
    for (const entry of cache) {
      if (entry.key === key) {
        hit = entry;
        break;
      }
    }
    if (hit !== null) {
      hit.freq += 1;
      hit.time = t;
      continue;
    }
    if (cache.length < capacity) {
      cache.push({ key: key, freq: 1, time: t });
      continue;
    }
    let victim = 0;
    for (let i = 1; i < cache.length; i++) {
      const a = cache[i];
      const b = cache[victim];
      if (a.freq < b.freq || (a.freq === b.freq && a.time < b.time)) {
        victim = i;
      }
    }
    evicted.push(cache[victim].key);
    cache[victim] = { key: key, freq: 1, time: t };
  }
  return evicted;
}

function solve(capacity, accesses) {
  if (capacity <= 0) return [];
  const state = new Map();
  const heap = [];
  const evicted = [];
  const less = (a, b) => a[0] < b[0] || (a[0] === b[0] && (a[1] < b[1] || (a[1] === b[1] && a[2] < b[2])));
  const push = (item) => {
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (!less(heap[i], heap[parent])) break;
      const tmp = heap[parent];
      heap[parent] = heap[i];
      heap[i] = tmp;
      i = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length > 0) {
      heap[0] = last;
      let i = 0;
      while (true) {
        const left = 2 * i + 1;
        const right = 2 * i + 2;
        let small = i;
        if (left < heap.length && less(heap[left], heap[small])) small = left;
        if (right < heap.length && less(heap[right], heap[small])) small = right;
        if (small === i) break;
        const tmp = heap[small];
        heap[small] = heap[i];
        heap[i] = tmp;
        i = small;
      }
    }
    return top;
  };
  for (let t = 0; t < accesses.length; t++) {
    const key = accesses[t];
    const current = state.get(key);
    if (current !== undefined) {
      current[0] += 1;
      current[1] = t;
      push([current[0], current[1], key]);
      continue;
    }
    if (state.size < capacity) {
      state.set(key, [1, t]);
      push([1, t, key]);
      continue;
    }
    let victim = null;
    while (heap.length > 0) {
      const top = pop();
      const known = state.get(top[2]);
      if (known !== undefined && known[0] === top[0] && known[1] === top[1]) {
        victim = top[2];
        break;
      }
    }
    state.delete(victim);
    evicted.push(victim);
    state.set(key, [1, t]);
    push([1, t, key]);
  }
  return evicted;
}
